{"content": "{
  "main_characters": [
    {
      "name": "沈听澜",
      "role": "protagonist",
      "identity": "重生的体操教练/现在回到国家队运动员时期，主项平衡木，副项自由操",
      "traits": ["表面冷静自持", "内心愧疚深重", "技术偏执完美主义", "嘴硬心软", "责任感极强"],
      "overt_motivation": "弥补前世的过错，保护队友不再受伤",
      "covert_motivation": "获得队友的原谅，证明自己不是那个\"故意害人的人\"",
      "secret_fear": "害怕自己无论怎么努力，都无法改变队友眼中那个\"凶手\"的形象；害怕对方永远不会相信自己",
      "misperception_of_other": "以为队友不记得前世，只是单纯地恐惧她（不知道队友也重生了）",
      "hidden_connection": "前世两人曾是恋人，因为那场事故而分离。沈听澜至今爱着她。"
    },
    {
      "name": "温时予",
      "role": "deuteragonist",
      "identity": "重生的体操运动员，主项高低杠，副项平衡木，前世因\"被推下平衡木\"而瘫痪退役",
      "traits": ["外表温柔明朗", "内心防备警惕", "坚韧不屈", "敏锐聪慧", "极强的求胜欲"],
      "overt_motivation": "查明前世事故的真相，重新站上赛场证明自己",
      "covert_motivation": "想要相信沈听澜不是故意的，却又害怕再次被伤害",
      "secret_fear": "害怕自己爱上的人真的想杀自己；害怕这一世的\"善意\"只是为了更彻底地毁掉她",
      "misperception_of_other": "以为沈听澜前世故意推她下平衡木（实际上是记忆被篡改）",
      "hidden_connection": "前世与沈听澜是恋人。瘫痪后沈听澜照顾她多年直到她去世，但温时予重生时的记忆停留在\"被推下\"的那一刻。"
    }
  ],
  "supporting_characters": [
    {
      "name": "江映真",
      "function": "反转点",
      "identity": "国家队体操运动员，主项平衡木，沈听澜和温时予的队友",
      "description": "前世暗中破坏器械的真凶。表面与两人交好，实际嫉妒心极强。她本想害沈听澜，却阴差阳错让温时予受伤。这一世她发现两人都\"变了\"，开始暗中观察。是揭开记忆错位真相的关键人物。"
    },
    {
      "name": "顾斐然",
      "function": "助力",
      "identity": "国家队体操队总教练",
      "description": "严厉但公正的老教练，慧眼识珠。前世因温时予受伤一蹶不振，这一世在沈听澜的建议下重新审视训练方法。是推动两位主角走向国际赛场的关键推手。"
    },
    {
      "name": "陆晚亭",
      "function": "助力",
      "identity": "国家队队医",
      "description": "温柔细致的运动医学专家，温时予的闺蜜。最早察觉温时予\"变了\"，也最早发现沈听澜和温时予之间微妙的张力。在误会解开后成为两人感情的助攻。"
    },
    {
      "name": "何嘉言",
      "function": "阻碍",
      "identity": "国家队体操运动员，主项自由操",
      "description": "性格直率但有些鲁莽的队友，与江映真走得近。前世曾传播沈听澜\"故意推人\"的谣言（实际是被江映真利用）。这一世成为考验两位主角信任的\"试金石\"。"
    },
    {
      "name": "方越",
      "function": "助力",
      "identity": "国家队器械维护负责人",
      "description": "沉默寡言的技术人员。前世曾发现器械异常但被江映真的父亲（体育局官员）压下。这一世在沈听澜的暗中引导下，成为揭露真相的关键证人。"
    },
    {
      "name": "江父",
      "function": "阻碍",
      "identity": "体育局分管官员，江映真的父亲",
      "description": "前世为保护女儿压下器械故障的调查。这一世依然是阻碍真相浮出水面的势力，但在铁证面前最终妥协。"
    }
  ],
  "relationship_dynamics": "【初始关系】沈听澜和温时予表面是队友，实际一方想补偿（沈），一方想复仇/防备（温）。两人都隐藏着\"重生者\"的身份，在朝夕相处中小心试探对方。\n\n【第一转折：发现彼此都重生】沈听澜无意间说出只有前世才知道的细节，温时予震惊地意识到\"她也重生了\"。但这反而加深了温时予的恐惧——如果她也记得前世，那岂不是会更彻底地提防自己？\n\n【核心张力】两人的记忆版本不同：沈听澜记得自己是\"无意中推开她躲避掉落的器械\"，温时予记得的是\"被从背后推下\"。这个记忆错位的谜团贯穿前期，成为两人无法坦诚的屏障。\n\n【第二转折：真相浮现】在沈听澜的暗中调查下，江映真的破坏行为逐渐浮出水面。温时予开始动摇——也许沈听澜真的是在保护她？但她不敢相信，因为相信意味着承认自己恨错了人。\n\n【情感变化轨迹】防备→怀疑→动摇→信任→相爱。两人在训练和比赛中培养出新的默契，在生活中逐渐打开心扉。当真相彻底揭开时，温时予崩溃大哭——她曾那样恨一个为了救她而背负骂名的人。\n\n【最终状态】两人携手站上国际赛场，以双人项目和各自的单项证明自己。误会消解后的爱情比前世更坚定，因为这一次她们选择了坦诚和信任。"
}
", "path": "characters.json"}

